/**
 * Locations as Triple C submitted them, for MULTIPLIER and PORTA FARM only.
 *
 * Extracted from the two Location Master Templates in
 * `MASTER TEMPLATES - TRIPLE C SUBMISSIONS/`. Codes are the client's own —
 * MUL100, PGH1, PSLCr1 — not generated, because these are what farm staff use
 * and what the sow cards reference.
 *
 * This is not the whole of both templates. 453 of the 703 submitted rows carry
 * a Location Code that is not unique within their own template, which the
 * template itself requires ("Unique code per tenant"), so they cannot be keyed
 * on it. `docs/triple-c-location-code-queries.md` lists every one for Triple C
 * to re-code; this file is regenerated and the seed re-run once they answer.
 *
 * `parent` is the parent's own code, resolved by code prefix — MUGR1P1 sits
 * under MUGR1 — which attached every child unambiguously. A child whose parent
 * shed had a duplicate code is in the query list rather than here, because its
 * place in the hierarchy is genuinely unknown.
 *
 * DO NOT EDIT BY HAND. Regenerate from the templates.
 */
export interface FarmLocationSeedRow {
  /** Which submitted template this row came from. */
  farm: 'MULTIPLIER' | 'PORTA';
  /** The client's own code, unique within this dataset. */
  code: string;
  /** location_type_master.type_code. */
  type: 'FARM' | 'SHED' | 'PEN' | 'CRATE' | 'CAGE';
  /** Parent's `code`, or '__FARM__' for a shed under its own farm. Absent on a farm. */
  parent?: string;
  name: string;
  address?: string;
  areaSize?: number;
  /** uom_master.uom_code — SQM or HECTARE. */
  areaUom?: string;
  maxCapacity?: number;
  /** uom_master.uom_code. The templates say "NUMBERS", which is a headcount. */
  capacityUom?: string;
  /** STORE or SILO. */
  storageType?: string;
  /** The silo or store's own name-number: MGH1, PSL FS - 01, STORE. */
  storageName?: string;
  siloCapacityKg?: number;
  siloReorderDays?: number;
  downtimeDays?: number;
  feedInBags?: boolean;
}

